//! The version string every build reports, the commit it was built from, and the link
//! configuration for everything cargo itself links: the application binary and the host test
//! binaries. The localization catalog is generated by the platform layer's own build script.
//!
//! **Link configuration is a build script rather than `.cargo/config.toml`** because the library
//! search path is not a constant: Linux distributions publish their SDL locations through
//! pkg-config, and a hardcoded guess fails as an "SDL2 not found" link error a long way from its
//! cause.

use std::path::{Path, PathBuf};
use std::process::Command;

#[path = "build_support/host_link.rs"]
mod host_link;

fn main() {
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-changed=build_support/host_link.rs");
    emit_version();
    emit_build_sha();
    // Host link configuration (SDL, GL, the nanosvg object): shared with the gfx layer's build
    // script, which needs the same lines for its own test binary.
    host_link::emit(Path::new(env!("CARGO_MANIFEST_DIR")).parent().expect("rust-modules has a parent"));
}

/// Publish `PLX_VERSION` — the version this build reports: the manifest's own for a release build
/// (`PLX_RELEASE=1`), and the next minor with `-dev` for every other build, so a working tree never
/// reports itself as the last published release.
fn emit_version() {
    println!("cargo:rerun-if-env-changed=PLX_RELEASE");
    let pkg = std::env::var("CARGO_PKG_VERSION").expect("CARGO_PKG_VERSION");
    let (major, minor, _patch) = triplet(&pkg);
    let release = std::env::var("PLX_RELEASE").is_ok_and(|v| !v.is_empty());
    let version = if release { pkg.clone() } else { format!("{major}.{}.0-dev", minor + 1) };
    println!("cargo:rustc-env=PLX_VERSION={version}");
}

/// The manifest version as three integers, or a build failure: `0.5.0-rc.1` must fail, not
/// silently become (0, 5, 1).
fn triplet(pkg: &str) -> (u64, u64, u64) {
    let parts: Vec<&str> = pkg.split('.').collect();
    let [major, minor, patch] = parts[..] else {
        panic!("Cargo.toml version {pkg:?} is not three dot-separated integers");
    };
    let int = |part: &str| {
        part.parse()
            .unwrap_or_else(|_| panic!("Cargo.toml version {pkg:?} is not three integers"))
    };
    (int(major), int(minor), int(patch))
}

/// Publish `PLX_BUILD_SHA` — the short commit this binary was built from, so the About screen can
/// name the exact source a bug report came from. `PLX_VERSION` alone cannot: every commit on trunk
/// between two releases reports the identical `X.Y.0-dev`.
///
/// Best-effort: a source tarball has no `.git` at all and must still build, so a failed `git` falls
/// back to `"unknown"`. Re-run on whatever moves this worktree's `HEAD` — a commit, checkout or
/// rebase all touch its reflog — via `git rev-parse --git-path`, which resolves `logs/HEAD`/`HEAD`
/// under a linked worktree's own `.git/worktrees/<name>/`, not the main checkout's.
fn emit_build_sha() {
    let sha = git_short_sha().unwrap_or_else(|| "unknown".into());
    println!("cargo:rustc-env=PLX_BUILD_SHA={sha}");
    for rel in ["logs/HEAD", "HEAD"] {
        // Only a file that exists: a MISSING rerun-if-changed path is stale on every invocation,
        // and `logs/HEAD` is absent in a repository with `core.logAllRefUpdates=false`.
        if let Some(path) = git_path(rel).filter(|p| p.exists()) {
            println!("cargo:rerun-if-changed={}", path.display());
        }
    }
}

fn git_short_sha() -> Option<String> {
    let out = Command::new("git")
        .args(["rev-parse", "--short", "HEAD"])
        .output()
        .ok()?;
    if !out.status.success() {
        return None;
    }
    let sha = String::from_utf8(out.stdout).ok()?;
    let sha = sha.trim();
    (!sha.is_empty()).then(|| sha.to_string())
}

/// The absolute path `git` resolves `<rel>` (a path inside `.git`) to for the CURRENT worktree.
fn git_path(rel: &str) -> Option<PathBuf> {
    let out = Command::new("git")
        .args(["rev-parse", "--path-format=absolute", "--git-path", rel])
        .output()
        .ok()?;
    if !out.status.success() {
        return None;
    }
    let p = String::from_utf8(out.stdout).ok()?;
    Some(PathBuf::from(p.trim()))
}
